"use client";

import { useEffect, useRef, useState } from "react";
import { Music2, Pause, Play, Volume2, VolumeX } from "lucide-react";

export default function MusicPlayer() {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(false);
  const [hint, setHint] = useState(true);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.muted = muted;
  }, [muted]);

  async function togglePlayback() {
    const audio = audioRef.current;
    if (!audio) return;
    setHint(false);
    if (playing) {
      audio.pause();
      setPlaying(false);
      return;
    }
    try {
      await audio.play();
      setPlaying(true);
    } catch (error) {
      console.error("Background music could not be played.", error);
      setPlaying(false);
    }
  }

  return (
    <div className="fixed bottom-5 right-4 z-50 flex items-center gap-2 sm:bottom-7 sm:right-7">
      <audio
        ref={audioRef}
        loop
        preload="none"
        onPause={() => setPlaying(false)}
        onPlay={() => setPlaying(true)}
        // Add your licensed music file at public/audio/wedding-melody.mp3.
        src="/audio/wedding-melody.mp3"
      />
      {hint && <span className="absolute bottom-full right-0 mb-2 whitespace-nowrap rounded-full bg-white/95 px-3 py-2 text-[10px] text-stone-600 shadow-lg">Tap to play our song</span>}
      <button onClick={togglePlayback} aria-label={playing ? "Pause wedding music" : "Play wedding music"} className="music-disc relative flex h-12 w-12 items-center justify-center rounded-full border border-white/20 shadow-xl transition hover:scale-105">
        <span className={`absolute inset-0 rounded-full border border-white/10 ${playing ? "music-playing" : ""}`} />
        <span className="z-10 flex h-4 w-4 items-center justify-center rounded-full bg-[#D4AF37]">
          {playing ? <Pause size={8} fill="currentColor" /> : <Play size={8} fill="currentColor" />}
        </span>
      </button>
      <button onClick={() => setMuted((value) => !value)} aria-label={muted ? "Unmute music" : "Mute music"} className="flex h-10 w-10 items-center justify-center rounded-full border border-white/60 bg-white/90 text-stone-700 shadow-lg">
        {muted ? <VolumeX size={15} /> : playing ? <Volume2 size={15} /> : <Music2 size={15} />}
      </button>
    </div>
  );
}
